<script setup lang="ts">
import { reactive,ref,computed,watch } from 'vue';import { useRoute,useRouter } from 'vue-router';
import { relationEndpoint,goSaved,api,mutate,query,types,text,opts,can,useDirty,useTask,type DTO,type Page } from './shared';
import RemoteSelect from './RemoteSelect.vue';import TaskForm from './TaskForm.vue';import PageState from './PageState.vue';import {useForm,catalogForm} from './forms';
const route=useRoute(),router=useRouter(),{form,open}=useForm(),{busy,error,notice,run}=useTask();
const kind=ref(String(route.query.kind??'')),type=ref('platform_account'),data=reactive({name:'',provider_name:'',purpose:'',platform_id:'',company_id:'',person_id:'',owning_department_id:'',identifier:'',login_method:'unknown',account_role:'unknown',scope_label:'',source_note:'手工登记',usage_mode:'normal',relation_target:'',relation_type:'uses'}),attrs=reactive<Record<string,string>>({}),saved=ref(false),duplicate=ref<DTO<'ResourceSummary'>[]>([]),confirmedDuplicate=ref(false),createdRefs=ref<string[]>([]),createdLabels=ref<Record<string,string>>({});
const typeFields:Record<string,string[]>={platform_account:[],mailbox_account:[],api_key:['external_key_id'],service_subscription:['plan','seats','billing_cycle','expires_on'],business_space:['external_instance_id','scope_label','environment','region'],application:['endpoint','environment','tech_stack'],api_service:['endpoint','external_instance_id','metric_scope','environment'],cloud_resource:['external_instance_id','resource_kind','region','specification','environment','endpoint'],domain:['domain_name','registrar','registered_on','expires_on','renewal_note']};
const fieldNames:Record<string,string>={external_key_id:'外部密钥标识（公开部分）',plan:'套餐',seats:'席位数',billing_cycle:'计费周期',expires_on:'到期日',external_instance_id:'外部实例标识',scope_label:'业务范围',environment:'运行环境',region:'区域',endpoint:'访问地址',tech_stack:'技术栈（逗号分隔）',metric_scope:'指标范围',resource_kind:'云资源类型',specification:'规格',domain_name:'域名',registrar:'注册商',registered_on:'注册日',renewal_note:'续期说明'};
const choices=[['company','公司主体','管理公司或法律主体'],['identity','注册身份','手机号、邮箱或第三方身份'],['platform','平台','阿里云、DeepSeek 等平台目录'],['resource','实际资源','账号、密钥、订阅、应用或云资源']];
const dirty=computed(()=>!saved.value&&(Boolean(data.name||data.identifier||data.purpose)||Object.values(attrs).some(Boolean)));useDirty(()=>dirty.value,()=>busy.value);
watch(type,()=>{data.relation_target='';data.relation_type='uses';});watch(()=>data.relation_type,()=>{data.relation_target='';});
watch([()=>data.name,type,()=>data.platform_id],()=>{duplicate.value=[];confirmedDuplicate.value=false;});
function quick(k:string){open(catalogForm(k,async row=>{if(k==='company')data.company_id=row.id;if(k==='platform')data.platform_id=row.id;createdRefs.value.push(row.name);createdLabels.value[row.id]=row.name;notice.value='目录已独立保存；即使取消本次资源登记也会保留。';}));}
function catalog(){open(catalogForm(kind.value,async row=>{saved.value=true;await goSaved(router,`/directory/${kind.value}/${row.id}`);}));}
async function save(){await run(async()=>{
 if(!confirmedDuplicate.value){const found=await api.get<Page<DTO<'ResourceSummary'>>>('/resources/duplicate-candidates'+query({name:data.name,type_code:type.value,platform_id:data.platform_id}));if(found.items.length){duplicate.value=found.items;return;}}
 const attributes:Record<string,unknown>={};for(const key of typeFields[type.value]??[])if(attrs[key])attributes[key]=key==='seats'?Number(attrs[key]):key==='tech_stack'?attrs[key].split(/[,，]/).map(x=>x.trim()).filter(Boolean):attrs[key];
 const payload={type_code:type.value as DTO<'ResourceType'>,name:data.name,purpose:data.purpose||null,provider_name:data.provider_name||null,platform_id:data.platform_id||null,owning_department_id:data.owning_department_id||null,usage_mode:data.usage_mode as 'normal'|'test'|'standby',source_note:data.source_note,attributes,people:data.person_id?[{person_id:data.person_id,role:'owner'}]:[],company_links:data.company_id?[{company_id:data.company_id,role:'owner'}]:[],relations:data.relation_target?[{target_id:data.relation_target,relation_type:data.relation_type as DTO<'RelationType'>}]:[],...(data.identifier&&['platform_account','mailbox_account'].includes(type.value)?{account:{identifier:data.identifier,login_methods:[data.login_method as DTO<'LoginMethod'>],account_role:data.account_role as DTO<'AccountRole'>,scope_label:data.scope_label||null}}:{})} as DTO<'ResourceCreate'>;
 const row=await mutate<DTO<'ResourceView'>>('/resources',payload);saved.value=true;data.identifier='';await goSaved(router,'/resources/'+row.id);
 });}
</script>
<template><header class="page-heading"><div><h1>登记</h1><p>先明确登记对象，再保存已知信息。关联与补充资料可以稍后完善。</p></div><RouterLink to="/resources" class="btn-secondary">返回清单</RouterLink></header><section class="feishu-section max-w-4xl"><div class="grid grid-cols-2 gap-2 border-b border-gray-100 p-3 sm:grid-cols-4"><button v-for="[key,name,hint] in choices" :key="key" type="button" class="rounded-lg border p-3 text-left" :class="kind===key?'border-accent-400 bg-accent-50':'border-gray-200 hover:bg-gray-50'" @click="kind=key"><strong class="text-sm">{{name}}</strong><span class="mt-1 block text-[11px] leading-4 text-gray-500">{{hint}}</span></button></div><div v-if="!kind" class="p-6 text-sm text-gray-500">请选择你要登记的对象。</div><div v-else-if="kind!=='resource'" class="p-5"><p class="mb-3 text-sm text-gray-600">{{text(kind)}}作为独立目录对象保存，可在资源登记时引用。</p><button v-if="can('catalog.write')" class="btn-primary" @click="catalog">填写{{text(kind)}}</button><p v-else class="text-sm text-gray-500">当前账号不能维护目录，请联系资源管理员。</p></div><form v-else class="p-4 md:p-5" @submit.prevent="save"><PageState :error="error" :notice="notice" @retry="save"/><fieldset :disabled="busy" class="space-y-4"><div class="grid gap-3 sm:grid-cols-2"><label><span class="admin-form-label">资源类型 <b>*</b></span><select v-model="type" class="admin-field"><option v-for="(name,key) in types" :value="key">{{name}}</option></select></label><label><span class="admin-form-label">名称 <b>*</b></span><input v-model="data.name" class="admin-field" required maxlength="200" placeholder="团队能辨认的名称"></label><label><span class="admin-form-label">提供方</span><input v-model="data.provider_name" class="admin-field" maxlength="200"></label><label><span class="admin-form-label">用途</span><input v-model="data.purpose" class="admin-field" maxlength="2000"></label></div><details class="rounded-lg border border-gray-200 p-3"><summary class="cursor-pointer text-xs font-medium text-gray-700">类型资料与账号标识（选填）</summary><div class="mt-3 grid gap-3 sm:grid-cols-2"><template v-if="['platform_account','mailbox_account'].includes(type)"><label><span class="admin-form-label">登录账号 / 邮箱标识</span><input v-model="data.identifier" class="admin-field" maxlength="320" autocomplete="off"><span class="text-[11px] text-gray-500">加密保存并脱敏展示；不要填写密码。</span></label><label><span class="admin-form-label">登录方式</span><select v-model="data.login_method" class="admin-field"><option v-for="o in opts(['unknown','password','otp','qr','sso','api_token'])" :value="o.value">{{o.label}}</option></select></label><label><span class="admin-form-label">账号角色</span><select v-model="data.account_role" class="admin-field"><option v-for="o in opts(['unknown','master','administrator','member','service'])" :value="o.value">{{o.label}}</option></select></label><label><span class="admin-form-label">账号范围</span><input v-model="data.scope_label" class="admin-field"></label></template><label v-for="key in typeFields[type]" :key="key"><span class="admin-form-label">{{fieldNames[key]}}</span><select v-if="key==='billing_cycle'" v-model="attrs[key]" class="admin-field"><option value="">待补充</option><option v-for="v in ['month','year','custom']" :value="v">{{text(v)}}</option></select><input v-else v-model="attrs[key]" class="admin-field" :type="key.endsWith('_on')?'date':key==='seats'?'number':'text'" min="0" maxlength="2000"></label></div></details><details class="rounded-lg border border-gray-200 p-3"><summary class="cursor-pointer text-xs font-medium text-gray-700">归属、责任与关联（选填）</summary><p class="mt-2 text-xs text-gray-500">先记录待确认关系，不要求补齐六层。缺失不会阻止建档，也不会自动生成上游。</p><div class="mt-3 grid gap-3 sm:grid-cols-2"><label><span class="admin-form-label">所属平台 <button v-if="can('catalog.write')" type="button" class="text-link float-right" aria-label="快速新增平台" @click="quick('platform')">快速新增</button></span><RemoteSelect v-model="data.platform_id" endpoint="/platforms" label="所属平台" :selected-label="createdLabels[data.platform_id]"/></label><label><span class="admin-form-label">所属公司 <button v-if="can('catalog.write')" type="button" class="text-link float-right" aria-label="快速新增公司" @click="quick('company')">快速新增</button></span><RemoteSelect v-model="data.company_id" endpoint="/companies" label="所属公司" :selected-label="createdLabels[data.company_id]"/></label><label><span class="admin-form-label">负责人（待确认）</span><RemoteSelect v-model="data.person_id" endpoint="/people" label="负责人"/></label><label><span class="admin-form-label">所属部门</span><RemoteSelect v-model="data.owning_department_id" endpoint="/departments" label="所属部门"/></label><label v-if="!['platform_account','mailbox_account'].includes(type)"><span class="admin-form-label">关联资源</span><RemoteSelect v-model="data.relation_target" :endpoint="relationEndpoint(data.relation_type)" label="关联资源"/></label><label v-if="!['platform_account','mailbox_account'].includes(type)"><span class="admin-form-label">关系方向：本资源 → 所选对象</span><select v-model="data.relation_type" class="admin-field"><option v-for="v in ['uses','managed_by','part_of','depends_on',...(type==='business_space'?['contains']:[])]" :value="v">{{text(v)}}</option></select></label></div></details><label class="block"><span class="admin-form-label">信息来源 <b>*</b></span><input v-model="data.source_note" class="admin-field" required maxlength="500"></label><div v-if="duplicate.length" class="admin-notice admin-notice-warning"><p>发现同名候选，请核对后决定是否新增：</p><ul class="my-2"><li v-for="r in duplicate" :key="r.id"><RouterLink :to="'/resources/'+r.id" class="text-link">{{r.name}} · {{r.code}}</RouterLink></li></ul><label class="flex gap-2"><input v-model="confirmedDuplicate" type="checkbox">已核对，仍需建立独立记录</label></div><p v-if="createdRefs.length" class="text-xs text-gray-500">已独立新增：{{createdRefs.join('、')}}</p><div class="flex justify-end"><button class="btn-primary" :disabled="busy">{{busy?'保存中…':'保存并查看'}}</button></div></fieldset></form></section><TaskForm v-if="form" v-bind="form" @close="form=undefined"/></template>
